import yaml
with open('registry.yaml') as f:
    reg = yaml.safe_load(f)

# Find all v2 experiments with eval results
v2_cells = {}
for eid, e in reg['experiments'].items():
    if '_v2_' in eid and e.get('metrics') and e['metrics'].get('CAR') is not None:
        # Skip non-numeric
        car = e['metrics'].get('CAR')
        tsr = e['metrics'].get('TSR')
        if isinstance(car, (int, float)):
            v2_cells[eid] = {
                'CAR': car, 
                'TSR': tsr,
                'total_episodes': e['metrics'].get('total_episodes'),
                'conclusion': e.get('conclusion')
            }

# Also get vanilla v2
for eid, e in reg['experiments'].items():
    if 'vanilla' in eid.lower() and '_v2' in eid.lower() and e.get('metrics'):
        car = e['metrics'].get('CAR')
        tsr = e['metrics'].get('TSR')
        if isinstance(car, (int, float)):
            v2_cells[eid] = {
                'CAR': car,
                'TSR': tsr,
                'total_episodes': e['metrics'].get('total_episodes'),
                'conclusion': e.get('conclusion')
            }

# Also v2 retrain vanilla
for eid, e in reg['experiments'].items():
    if 'vanilla_retrain' in eid.lower() and e.get('metrics'):
        car = e['metrics'].get('CAR')
        tsr = e['metrics'].get('TSR')
        if isinstance(car, (int, float)):
            v2_cells[eid] = {
                'CAR': car,
                'TSR': tsr,
                'total_episodes': e['metrics'].get('total_episodes'),
                'conclusion': e.get('conclusion')
            }

for k in sorted(v2_cells.keys()):
    print(f'{k}: {v2_cells[k]}')
"

